package org.nexusportal.layer;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public class OverlayService extends Service {
 private WindowManager wm;private View bubble;private View layer;private boolean shown=false;private static final String CHANNEL="nexusportal_overlay";
 @Override public void onCreate(){super.onCreate();if(!Settings.canDrawOverlays(this)){stopSelf();return;}wm=(WindowManager)getSystemService(WINDOW_SERVICE);createNotification();createWindows();}
 private void createNotification(){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel(CHANNEL,"NexusPortal overlay",NotificationManager.IMPORTANCE_LOW));Intent stop=new Intent(this,OverlayService.class);stop.setAction("STOP");PendingIntent pi=PendingIntent.getService(this,0,stop,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification n=new Notification.Builder(this,CHANNEL).setContentTitle("NexusPortal overlay active").setContentText("No observation or AI connection").setSmallIcon(android.R.drawable.ic_menu_view).addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,"Stop",pi).build()).build();startForeground(17,n);}
 private void createWindows(){int type=WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY;WindowManager.LayoutParams lp=new WindowManager.LayoutParams(-1,-1,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);layer=new View(this){Paint p=new Paint(3);@Override protected void onDraw(Canvas c){super.onDraw(c);if(!shown)return;p.setColor(Color.argb(190,109,227,212));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(8);float w=getWidth(),h=getHeight();c.drawCircle(w*.5f,h*.45f,Math.min(w,h)*.19f,p);c.drawLine(w*.2f,h*.67f,w*.78f,h*.54f,p);}};wm.addView(layer,lp);
 TextView b=new TextView(this);b.setText("%");b.setTextSize(30);b.setTextColor(Color.rgb(17,34,53));b.setGravity(Gravity.CENTER);b.setBackgroundTintList(null);b.setBackgroundColor(Color.rgb(109,227,212));WindowManager.LayoutParams bp=new WindowManager.LayoutParams(64,64,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);bp.gravity=Gravity.TOP|Gravity.LEFT;bp.x=30;bp.y=220;b.setOnClickListener(v->{Intent config=new Intent(this,MainActivity.class);config.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);startActivity(config);});b.setOnLongClickListener(v->{stopSelf();return true;});wm.addView(b,bp);bubble=b;}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null){String action=intent.getAction();if("STOP".equals(action)){stopSelf();return START_NOT_STICKY;}if("TOGGLE_ANNOTATIONS".equals(action)){shown=!shown;if(layer!=null)layer.invalidate();}if("HIDE_ANNOTATIONS".equals(action)){shown=false;if(layer!=null)layer.invalidate();}}return START_NOT_STICKY;}
 @Override public void onDestroy(){if(wm!=null){if(bubble!=null)wm.removeView(bubble);if(layer!=null)wm.removeView(layer);}super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
}
